def tbl(headers,rows):
 t=doc.add_table(rows=1,cols=len(headers));t.style='Table Grid'
 for c,v in zip(t.rows[0].cells,headers):
  c.text=v;shade=OxmlElement('w:shd');shade.set(qn('w:fill'),B);c._tc.get_or_add_tcPr().append(shade)
  for pp in c.paragraphs:
   for rr in pp.runs:rr.font.color.rgb=RGBColor.from_string(W);rr.font.bold=True
 repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
 for row in rows:
  cells=t.add_row();keep=OxmlElement('w:cantSplit');cells._tr.get_or_add_trPr().append(keep)
  for c,v in zip(cells.cells,row):c.text=str(v)
 return t
