def box(sl,x,y,w,hh,fill=W):
 sh=sl.shapes.add_shape(MSO_SHAPE.RECTANGLE,PI(x),PI(y),PI(w),PI(hh));sh.fill.solid();sh.fill.fore_color.rgb=PC.from_string(fill);sh.line.fill.background();return sh
def tx(sl,t,x,y,w,hh,size=19,fill=C,bold=False,font='Montserrat'):
 sh=sl.shapes.add_textbox(PI(x),PI(y),PI(w),PI(hh));tf=sh.text_frame;tf.word_wrap=True;tf.margin_left=tf.margin_right=PI(.02);tf.margin_top=tf.margin_bottom=0
 for i,s in enumerate(t.split('\n')):
  pp=tf.paragraphs[0] if i==0 else tf.add_paragraph();pp.text=s;pp.font.name=font;pp.font.size=PP(size);pp.font.color.rgb=PC.from_string(fill);pp.font.bold=bold;pp.space_after=PP(6)
 return sh
